     1	// Generic dialog chrome — overlay + panel + actions row. Component-specific content styling
     2	// (title, fields, consent copy, etc.) belongs in the consuming organism's own recipe, not here —
     3	// see e.g. zimmSubscribeModal.css.ts. Split out of the footer's original combined recipe so a
     4	// future non-subscribe modal has somewhere to register its own chrome and content separately.
     5	export const ZimmModal = {
     6	  parts: ['overlay', 'panel', 'actions'],
     7	  baseStyle: {
     8	    // Rendered through a portal, so it escapes any caller's stacking context.
     9	    overlay: {
    10	      position: 'fixed',
    11	      inset: 0,
    12	      // brand dark overlay (grey-900 base), not pure black
    13	      background: 'var(--zimm-color-opacity-50)',
    14	      display: 'flex',
    15	      alignItems: 'center',
    16	      justifyContent: 'center',
    17	      padding: 'var(--zimm-scale-l)',
    18	      // Chakra zIndices.overlay (1300). Must clear the sticky header, which sets
    19	      // zIndex: 'sticky' (1100) in header.ts. The portal target is document.body, so this
    20	      // competes in the root stacking context, not the caller's.
    21	      zIndex: 'overlay',
    22	    },
    23	    // Light surface — every current use case contrasts against a dark parent (the footer).
    24	    // maxWidth is deliberately NOT set here — ZimmModal takes it as a required prop, since each
    25	    // dialog type has its own Figma-specified size.
    26	    panel: {
    27	      backgroundColor: 'var(--zimm-color-bg-07)',
    28	      width: '100%',
    29	      padding: 'var(--zimm-scale-3xl)',
    30	    },
    31	    actions: { display: 'flex', gap: 'var(--zimm-scale-m)', justifyContent: 'flex-end' },
    32	  },
    33	};
