     1	import type { SystemStyleObject } from '@chakra-ui/react';
     2	
     3	// Figma Textfield flush variant (node 40000265:374): field/border/* tokens.
     4	// hover and filled (has value, unfocused) both darken to focus colour per Figma spec.
     5	const BORDER = {
     6	  default: 'var(--zimm-color-border-forms)', // #707070 — Figma field/border/default
     7	  hover: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/hover
     8	  filled: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/filled
     9	  focus: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/focus
    10	  error: 'var(--zimm-color-status-error)', // #9c0000 — Figma field/border/error
    11	} as const;
    12	
    13	// Figma field/border/inverse/default = white (opaque), inverse/error = #f98f8c (coral).
    14	// Figma does not spec inverse/hover or inverse/focus separately — same white as default.
    15	const BORDER_INVERSE = {
    16	  default: 'var(--zimm-color-text-inverse)',
    17	  hover: 'var(--zimm-color-text-inverse)',
    18	  filled: 'var(--zimm-color-text-inverse)',
    19	  focus: 'var(--zimm-color-text-inverse)',
    20	  error: 'var(--zimm-color-status-error-bg)', // #f98f8c
    21	} as const;
    22	
    23	// Figma: Textfield flush floated label — brand/font/size/250 (10px) / medium weight.
    24	const LABEL_FLOATED_SIZE = 'var(--zimm-font-size-4xs)';
    25	const LABEL_FLOATED_WEIGHT = 'var(--zimm-font-weight-medium)';
    26	// Figma: content div h-[36px] — pending alias/size/field/height token from the designer.
    27	// rem, not px: this height participates in a rem-derived measurement, so it has to scale with the
    28	// root font-size (WCAG 1.4.4 — see overrideStyling.md > Units). footer.css.ts's SIZE_SUBSCRIBE_SLOT
    29	// analogue in zimmSubscribeSection.css.ts (2.8125rem) documents itself as "36px content + 4px/4px
    30	// padding + 1px border"; freezing the content height in px broke that derivation as soon as the
    31	// root font-size moved — at 200% zoom the slot reached 90px while the field reached only 53px,
    32	// over-reserving by ~37px. (Dead space, not clipping — the no-layout-shift guarantee held either
    33	// way.) In rem it holds at every zoom level. This file is now developer-owned per the co-location
    34	// pattern (overrideStyling.md), but the value itself is still PROVISIONAL pending Kiera — this
    35	// should ride along with that sign-off, not land silently.
    36	const FIELD_CONTENT_HEIGHT = '2.25rem'; // 36px at the default 16px root
    37	// No opacity token in foundation yet — pending Tier 1 PR with UI-designer sign-off.
    38	const OPACITY_DISABLED = 0.4;
    39	
    40	const MOTION = 'var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)';
    41	
    42	/** State the component feeds in so the recipe can resolve the Figma colour cascade. */
    43	export type ZimmTextInputStyleProps = {
    44	  inverse?: boolean;
    45	  disabled?: boolean;
    46	  hasError?: boolean;
    47	  focused?: boolean;
    48	  /** Field has a value. Combined with `focused` this gives the floated-label state. */
    49	  filled?: boolean;
    50	};
    51	
    52	const palette = (inverse?: boolean) => (inverse ? BORDER_INVERSE : BORDER);
    53	
    54	/** Border colour precedence: disabled > error > focus > filled > default. */
    55	export const resolveBorderColour = ({ inverse, disabled, hasError, focused, filled }: ZimmTextInputStyleProps) => {
    56	  const p = palette(inverse);
    57	  if (disabled) return p.default;
    58	  if (hasError) return p.error;
    59	  if (focused) return p.focus;
    60	  if (filled) return p.filled;
    61	  return p.default;
    62	};
    63	
    64	/** In error the hover colour holds (error > hover); otherwise it darkens to focus. */
    65	export const resolveHoverBorderColour = (props: ZimmTextInputStyleProps) =>
    66	  props.hasError ? resolveBorderColour(props) : palette(props.inverse).hover;
    67	
    68	// Figma text/subtle = #666 for the floated/disabled label in light mode;
    69	// text/inverse/subtle = #969696 in inverse mode.
    70	export const resolveLabelColour = ({ inverse, disabled, focused, filled }: ZimmTextInputStyleProps) => {
    71	  const floated = Boolean(focused || filled);
    72	  if (disabled) return inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)';
    73	  if (inverse) return floated ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-inverse)';
    74	  return floated ? 'var(--zimm-color-text-secondary)' : 'var(--zimm-color-text-default)';
    75	};
    76	
    77	export const ZimmTextInput = {
    78	  parts: ['root', 'row', 'content', 'label', 'input', 'clearButton', 'helper', 'error'],
    79	  baseStyle: (props: ZimmTextInputStyleProps): Record<string, SystemStyleObject> => {
    80	    const { inverse, disabled, focused, filled } = props;
    81	    const floated = Boolean(focused || filled);
    82	    const textColour = inverse ? 'var(--zimm-color-text-inverse)' : 'var(--zimm-color-text-default)';
    83	
    84	    return {
    85	      root: {
    86	        display: 'block',
    87	        width: '100%',
    88	        opacity: disabled ? OPACITY_DISABLED : 1,
    89	      },
    90	
    91	      // Flush bottom-border row. Hover is a CSS pseudo-class, not JS state.
    92	      row: {
    93	        display: 'flex',
    94	        alignItems: 'center',
    95	        gap: 'var(--zimm-scale-xs)',
    96	        borderBottom: `var(--zimm-border-width-default) solid ${resolveBorderColour(props)}`,
    97	        paddingTop: 'var(--zimm-scale-2xs)',
    98	        paddingBottom: 'var(--zimm-scale-2xs)',
    99	        // not in Figma — UX animation on border-colour state changes
   100	        transition: `border-color ${MOTION}`,
   101	        _hover: disabled ? undefined : { borderBottomColor: resolveHoverBorderColour(props) },
   102	      },
   103	
   104	      // Figma: content flex-[1_0_0] h-[36px]
   105	      content: { flex: 1, position: 'relative', minHeight: FIELD_CONTENT_HEIGHT },
   106	
   107	      label: {
   108	        position: 'absolute',
   109	        left: 0,
   110	        fontFamily: 'var(--zimm-font-family-body)',
   111	        fontWeight: floated ? LABEL_FLOATED_WEIGHT : 'var(--zimm-font-weight-regular)',
   112	        fontSize: floated ? LABEL_FLOATED_SIZE : 'var(--zimm-font-size-2xs)',
   113	        lineHeight: floated ? undefined : 'var(--zimm-font-lineheight-2xs)',
   114	        color: resolveLabelColour(props),
   115	        top: floated ? 'var(--zimm-scale-3xs)' : '50%',
   116	        transform: floated ? 'none' : 'translateY(-50%)',
   117	        transition: `top ${MOTION}, transform ${MOTION}, font-size ${MOTION}, color ${MOTION}`,
   118	        whiteSpace: 'nowrap',
   119	      },
   120	
   121	      input: {
   122	        position: 'absolute',
   123	        bottom: 0,
   124	        left: 0,
   125	        right: 0,
   126	        width: '100%',
   127	        height: 'var(--zimm-scale-l)', // 20px — var, not 'l': theme.sizes has no 'l' key
   128	        background: 'transparent',
   129	        border: 'none',
   130	        outline: 'none',
   131	        fontFamily: 'var(--zimm-font-family-body)',
   132	        fontWeight: 'var(--zimm-font-weight-regular)',
   133	        fontSize: 'var(--zimm-font-size-2xs)',
   134	        color: textColour,
   135	        padding: 0,
   136	        opacity: floated ? 1 : 0,
   137	        cursor: disabled ? 'not-allowed' : 'text',
   138	        transition: `opacity ${MOTION}`,
   139	      },
   140	
   141	      clearButton: {
   142	        background: 'transparent',
   143	        border: 'none',
   144	        padding: 0,
   145	        cursor: 'pointer',
   146	        display: 'inline-flex',
   147	        alignItems: 'center',
   148	        justifyContent: 'center',
   149	        flexShrink: 0,
   150	        color: textColour,
   151	        // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size
   152	        // var, not 'xl': min-width/height resolve via theme.sizes (xl = 36rem), not theme.space
   153	        minWidth: 'var(--zimm-scale-xl)',
   154	        minHeight: 'var(--zimm-scale-xl)',
   155	        // WCAG 2.2 AA SC 2.4.7 — visible focus state
   156	        _focusVisible: {
   157	          outline: inverse
   158	            ? 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)'
   159	            : 'var(--zimm-focus-ring)',
   160	          outlineOffset: 'var(--zimm-focus-ring-offset-default)',
   161	          boxShadow: 'none',
   162	        },
   163	      },
   164	
   165	      helper: {
   166	        marginTop: 'var(--zimm-scale-2xs)',
   167	        marginBottom: 0,
   168	        marginInline: 0,
   169	        fontFamily: 'var(--zimm-font-family-body)',
   170	        fontSize: 'var(--zimm-font-size-3xs)',
   171	        color: inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)',
   172	      },
   173	
   174	      error: {
   175	        marginTop: 'var(--zimm-scale-2xs)',
   176	        marginBottom: 0,
   177	        marginInline: 0,
   178	        fontFamily: 'var(--zimm-font-family-body)',
   179	        fontSize: 'var(--zimm-font-size-2xs)',
   180	        fontStyle: 'normal',
   181	        fontWeight: 'var(--zimm-font-weight-regular)',
   182	        lineHeight: 'var(--zimm-font-lineheight-2xs)',
   183	        color: inverse ? 'var(--zimm-color-status-error-bg)' : 'var(--zimm-color-status-error)',
   184	      },
   185	    };
   186	  },
   187	};

