 68	/** Every Chakra prop that resolves through the registered `theme.space` scale — the full
 69	 *  padding/margin/gap/inset family, including directional and logical variants. */
 70	const SPACE_PROPS = new Set([
 71	  'padding',
 72	  'margin',
 73	  'gap',
 74	  'inset',
 75	  'p',
 76	  'm',
 77	  'px',
 78	  'py',
 79	  'mx',
 80	  'my',
 81	  'pt',
 82	  'pb',
 83	  'pl',
 84	  'pr',
 85	  'mt',
 86	  'mb',
 87	  'ml',
 88	  'mr',
 89	  'paddingTop',
 90	  'paddingBottom',
 91	  'paddingLeft',
 92	  'paddingRight',
 93	  'paddingBlock',
 94	  'paddingInline',
 95	  'paddingBlockStart',
 96	  'paddingBlockEnd',
 97	  'paddingInlineStart',
 98	  'paddingInlineEnd',
 99	  'marginTop',
100	  'marginBottom',
101	  'marginLeft',
102	  'marginRight',
103	  'marginBlock',
104	  'marginInline',
105	  'marginBlockStart',
106	  'marginBlockEnd',
107	  'marginInlineStart',
108	  'marginInlineEnd',
109	  'top',
110	  'left',
111	  'right',
112	  'bottom',
